@verbatim
<template id="finance-exchange-template">
<template v-if="view.name==='exchange'"><div v-if="rateError" class="notice error" role="alert">{{rateError}}</div><section class="panel exchange-panel"><div class="section-heading"><div><h2>Валютний калькулятор</h2><p>Змініть будь-яку суму — решту перерахуємо автоматично.</p></div><span class="surface-icon"><icon name="exchange"></icon></span></div><div class="currency-grid"><article v-for="currency in [{key:'cny',name:'Китайський юань',ticker:'CNY',symbol:'¥'},{key:'usd',name:'Tether',ticker:'USDT',symbol:'$'},{key:'uah',name:'Українська гривня',ticker:'UAH',symbol:'₴'}]" :key="currency.key" class="currency-card"><div class="currency-heading"><span>{{currency.symbol}}</span><div><h3>{{currency.ticker}}</h3><p>{{currency.name}}</p></div></div><label class="currency-input"><span>Сума {{currency.ticker}}</span><input v-model="exchange[currency.key]" :aria-label="'Сума '+currency.ticker" type="number" step="any" min="0" @input="recalculate(currency.key)"></label></article></div><div class="exchange-rates"><label class="field">Курс 1 CNY / USDT<input v-model="rates.cny_usdt" aria-label="Курс CNY до USDT" type="number" min="0.000001" step="any" @input="recalculate('cny')"></label><label class="field">Курс 1 USDT / UAH<input v-model="rates.usdt_uah" aria-label="Курс USDT до гривні" type="number" min="0.000001" step="any" @input="recalculate('usd')"></label><div class="exchange-note"><icon name="refresh"></icon><span>{{rateBusy?'Завантажуємо курси Coinbase…':rates.updated_at?'Курси Coinbase · '+dateLabel(rates.updated_at):'Курси можна ввести вручну'}}</span><small v-if="rates.usdt_cny">1 USDT = {{Number(rates.usdt_cny).toFixed(3)}} CNY</small></div></div></section></template>
</template>
@endverbatim
